package com.nigson.experience.distributor;import com.nigson.experience.platform.*;import java.time.Clock;import java.util.*;import org.springframework.context.annotation.*;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.JdbcTemplate;
@Configuration(proxyBeanMethods=false) public class DistributorConfiguration {
 @Bean @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="NIGSON_DISTRIBUTOR_COMMERCE_MODE",havingValue="mock") DistributorService.EntitlementPort localCommerceMock(Environment e){if(!Set.of("local","test").contains(e.getRequiredProperty("APP_ENV")))throw new IllegalArgumentException("DISTRIBUTOR_MOCK_LOCAL_ONLY");return new StatefulDistributorEntitlementMock();}
 @Bean @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="NIGSON_DISTRIBUTOR_COMMERCE_MODE",havingValue="http") DistributorService.EntitlementPort commerceHttp(Environment e){return DistributorEntitlementHttpClient.from(e);}
 @Bean DistributorService distributorService(JdbcTemplate jdbc,PlatformStore store,AuditWriter audit,Environment e,org.springframework.beans.factory.ObjectProvider<DistributorService.EntitlementPort> commerce){String configured=e.getProperty("NIGSON_DISTRIBUTOR_REQUIRED_DOCUMENT_TYPES","");Set<String> types;if(configured.isBlank())types=Set.of();else{var parsed=new LinkedHashSet<String>();for(String raw:configured.split(",",-1)){String value=raw.strip();if(!value.matches("[A-Z][A-Z0-9_]{1,39}")||!parsed.add(value))throw new IllegalArgumentException("INVALID_DISTRIBUTOR_DOCUMENT_TYPE_CONFIGURATION");}types=Set.copyOf(parsed);}String recipient=e.getProperty("NIGSON_DISTRIBUTOR_RECIPIENT_GROUP");if(recipient!=null&&!recipient.isBlank()&&!recipient.matches("[A-Za-z0-9][A-Za-z0-9._:-]{0,99}"))throw new IllegalArgumentException("INVALID_DISTRIBUTOR_RECIPIENT_GROUP_CONFIGURATION");return new DistributorService(jdbc,store,audit,Clock.systemUTC(),types,recipient,commerce.getIfAvailable());}
}
